/* sounds, made in the browser */
let actx;
function ac(){ try { actx = actx || new (window.AudioContext || window.webkitAudioContext)(); if (actx.state === "suspended") actx.resume(); } catch (e) {} return actx; }
const unlocked = () => actx && actx.state === "running";
function chime(base, gain, when){
  const c = ac(); if (!c) return;
  try {
    const t0 = c.currentTime + .02 + (when || 0), out = c.createGain(); out.gain.value = gain || .06; out.connect(c.destination);
    [[1, 1, 2], [2, .35, 1.4], [3, .14, .9], [4.2, .06, .5]].forEach(([r, g, d]) => {
      const o = c.createOscillator(); o.type = "sine"; o.frequency.value = base * r;
      const v = c.createGain(); v.gain.setValueAtTime(0, t0); v.gain.linearRampToValueAtTime(g, t0 + .01); v.gain.exponentialRampToValueAtTime(.0001, t0 + d);
      o.connect(v); v.connect(out); o.start(t0); o.stop(t0 + d + .05);
    });
  } catch (e) {}
}
let noiseBuf;
function noise(when, dur, type, freq, q, gain, sweep){
  const c = ac(); if (!c) return;
  try {
    if (!noiseBuf) { noiseBuf = c.createBuffer(1, c.sampleRate * 2, c.sampleRate); const d = noiseBuf.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1; }
    const t0 = c.currentTime + (when || 0), s = c.createBufferSource(); s.buffer = noiseBuf;
    const f = c.createBiquadFilter(); f.type = type; f.frequency.setValueAtTime(freq, t0); f.Q.value = q;
    if (sweep) f.frequency.exponentialRampToValueAtTime(sweep, t0 + dur);
    const g = c.createGain(); g.gain.setValueAtTime(gain, t0); g.gain.exponentialRampToValueAtTime(.0001, t0 + dur);
    s.connect(f); f.connect(g); g.connect(c.destination); s.start(t0, Math.random()); s.stop(t0 + dur + .05);
  } catch (e) {}
}
function thump(when, f0, f1, dur, gain){
  const c = ac(); if (!c) return;
  try {
    const t0 = c.currentTime + (when || 0), o = c.createOscillator(), g = c.createGain();
    o.type = "sine"; o.frequency.setValueAtTime(f0, t0); o.frequency.exponentialRampToValueAtTime(f1, t0 + dur * .6);
    g.gain.setValueAtTime(gain, t0); g.gain.exponentialRampToValueAtTime(.0001, t0 + dur);
    o.connect(g); g.connect(c.destination); o.start(t0); o.stop(t0 + dur + .05);
  } catch (e) {}
}

/* music: starts with the seal; the button hides itself if no song is loaded */
const music = $("music"), mBtn = $("music-btn");
let musicWanted = false, noMusic = false;
music.addEventListener("error", () => { noMusic = true; mBtn.hidden = true; });
function paintMusic(){ mBtn.classList.toggle("on", musicWanted); mBtn.setAttribute("aria-pressed", musicWanted); mBtn.setAttribute("aria-label", musicWanted ? "Pause music" : "Play music"); }
function setMusic(on){
  musicWanted = on;
  if (on && !noMusic) { music.volume = .7; const p = music.play(); if (p) p.catch(() => { musicWanted = false; paintMusic(); }); }
  else music.pause();
  paintMusic();
}
mBtn.addEventListener("click", () => setMusic(!musicWanted));
document.addEventListener("visibilitychange", () => { if (document.hidden) { music.pause(); stopDhol(); } else if (musicWanted && !noMusic) music.play().catch(() => {}); });

/* fireworks */
const cv = $("fw"), cx = cv.getContext("2d");
let rockets = [], sparks = [], fwRun = false, fwLast = 0, dpr = 1;
const PAL = [["#FFD27A", "#FFF3C4"], ["#FF8FB1", "#FFD6E3"], ["#9BE7C4", "#E9FFF4"], ["#C3B2FF", "#F1ECFF"], ["#FFB36B", "#FFE4C6"], ["#FFFFFF", "#FFE9B0"]];
function sizeCv(){ dpr = Math.min(2, devicePixelRatio || 1); cv.width = innerWidth * dpr; cv.height = innerHeight * dpr; cx.setTransform(dpr, 0, 0, dpr, 0, 0); }
sizeCv();
function launch(x, y, quiet){
  if (calm) return;
  const pal = PAL[Math.floor(Math.random() * PAL.length)];
  rockets.push({ x0: x + (Math.random() - .5) * 60, y0: innerHeight + 10, x, y, t: 0, d: .7 + Math.random() * .3, pal, quiet });
  if (!quiet && unlocked()) noise(0, .7, "bandpass", 500, 1.2, .05, 2400);
  if (!fwRun) { fwRun = true; fwLast = performance.now(); requestAnimationFrame(fwStep); }
}
function explode(r){
  const n = 64 + Math.floor(Math.random() * 30), sp = 110 + Math.random() * 90, ring = Math.random() < .3;
  for (let i = 0; i < n; i++) {
    const a = i / n * Math.PI * 2 + Math.random() * .12, v = ring ? sp : sp * (.35 + Math.random() * .75);
    sparks.push({ x: r.x, y: r.y, vx: Math.cos(a) * v, vy: Math.sin(a) * v, life: 1, dec: .55 + Math.random() * .45, c: Math.random() < .75 ? r.pal[0] : r.pal[1], tw: Math.random() < .35 });
  }
  if (sparks.length > 900) sparks.splice(0, sparks.length - 900);
  if (!r.quiet && unlocked()) { thump(0, 120, 40, .7, .35); noise(0, .9, "lowpass", 900, .7, .22, 120); for (let k = 0; k < 6; k++) noise(.25 + Math.random() * .5, .05, "highpass", 3000, .7, .05); }
}
function fwStep(t){
  const dt = Math.min(.04, (t - fwLast) / 1000); fwLast = t;
  cx.clearRect(0, 0, innerWidth, innerHeight);
  cx.globalCompositeOperation = "lighter";
  rockets = rockets.filter(r => {
    r.t += dt / r.d; const e = 1 - Math.pow(1 - Math.min(1, r.t), 2);
    const x = r.x0 + (r.x - r.x0) * e, y = r.y0 + (r.y - r.y0) * e;
    cx.strokeStyle = "rgba(255,230,180,.9)"; cx.lineWidth = 2; cx.beginPath(); cx.moveTo(x, y); cx.lineTo(x - (r.x - r.x0) * .03, y + 18); cx.stroke();
    if (r.t >= 1) { explode(r); return false; } return true;
  });
  for (const s of sparks) {
    s.vy += 70 * dt; s.vx *= .985; s.vy *= .985; s.x += s.vx * dt; s.y += s.vy * dt; s.life -= s.dec * dt;
    if (s.life <= 0) continue;
    let al = Math.min(1, s.life * 1.4); if (s.tw && s.life < .6) al *= Math.random() < .5 ? .2 : 1;
    cx.globalAlpha = al; cx.strokeStyle = s.c; cx.lineWidth = 2;
    cx.beginPath(); cx.moveTo(s.x - s.vx * .045, s.y - s.vy * .045); cx.lineTo(s.x, s.y); cx.stroke();
  }
  cx.globalAlpha = 1; cx.globalCompositeOperation = "source-over";
  sparks = sparks.filter(s => s.life > 0);
  if (rockets.length || sparks.length) requestAnimationFrame(fwStep); else { fwRun = false; cx.clearRect(0, 0, innerWidth, innerHeight); }
}
function colBounds(){ const r = document.querySelector(".inv").getBoundingClientRect(); return [Math.max(0, r.left), Math.min(innerWidth, r.right)]; }
function burstIn(yMax, quiet){ const [l, r] = colBounds(); launch(l + (r - l) * (.15 + Math.random() * .7), innerHeight * (.1 + Math.random() * .08) + Math.random() * Math.max(10, yMax - innerHeight * .18), quiet); }

/* gate: the wax seal cracks, the flap lifts and the card slides out */
const gate = $("gate");
let opened = false;
