  setTimeout(() => { gate.classList.add("under"); [659.25, 830.6, 987.8, 1318.5].forEach((f, i) => chime(f, .045, i * .1)); }, calm ? 0 : 950);
  setTimeout(() => { document.body.classList.remove("locked"); gate.classList.add("gone"); update(); }, calm ? 300 : 2500);
  setTimeout(() => { gate.hidden = true; for (let i = 0; i < 3; i++) setTimeout(() => burstIn(innerHeight * .45), i * 380); }, calm ? 1200 : 3300);
}
$("open").addEventListener("click", openGate);
$("seal").addEventListener("click", openGate);
if (preview) { gate.hidden = true; document.body.classList.remove("locked"); }

/* scroll engine */
const scenes = [...document.querySelectorAll("[data-scene]")];
const root = document.documentElement, skyS = $("s-sky"), mapS = $("s-map"), barS = $("s-bar");
let ticking = false, skyP = 0, skyVis = false, endVis = false;
function update(){
  const vh = innerHeight;
  for (const s of scenes) {
    const r = s.getBoundingClientRect();
    let p = calm ? ({ "s-sky": 0, "s-bar": .5 }[s.id] ?? 1) : -r.top / Math.max(1, r.height - vh);
    p = Math.min(1, Math.max(0, p));
    s.style.setProperty("--p", p.toFixed(4));
    if (s === skyS) { skyP = calm ? 0 : p; skyVis = r.bottom > 0 && r.top < vh; }
  }
  for (const w of wins) {
    const r = w.el.getBoundingClientRect();
    const o = calm ? 1 : Math.min(1, Math.max(0, (vh * .8 - r.top) / (r.height * .7)));
    w.el.style.setProperty("--o", o.toFixed(3));
    if (o > .55 && !w.rung) { w.rung = true; if (unlocked()) chime(784 + Math.random() * 200, .04); }
    if (o < .05) w.rung = false;
  }
  const er = $("end-art").getBoundingClientRect(); endVis = er.bottom > vh * .2 && er.top < vh * .6;
  const max = root.scrollHeight - vh;
  root.style.setProperty("--gp", max > 0 ? (scrollY / max).toFixed(4) : 0);
  ticking = false;
}
addEventListener("scroll", () => { if (!ticking) { ticking = true; requestAnimationFrame(update); } }, { passive: true });
addEventListener("resize", () => { sizeCv(); update(); });
update();

/* fireworks: automatic over the sky and at the end, and wherever guests tap */
setInterval(() => {
  if (calm || document.hidden || !gate.hidden && !preview) return;
  if (skyVis && skyP < .45) burstIn(innerHeight * (.5 - skyP * .7), preview);
  else if (endVis) { const r = $("end-art").getBoundingClientRect(); burstIn(Math.max(innerHeight * .2, r.top + r.height * .45), preview); }
}, 1300);
let tapped = false;
$("sky-stage").addEventListener("click", e => { launch(e.clientX, Math.min(e.clientY, innerHeight * .75)); if (!tapped) { tapped = true; skyS.style.setProperty("--hint", 0); } });
$("end-art").addEventListener("click", e => launch(e.clientX, Math.min(e.clientY, innerHeight * .7)));
$("light-sky").addEventListener("click", () => { const r = $("end-art").getBoundingClientRect(); const top = Math.max(innerHeight * .25, r.top + r.height * .5); for (let i = 0; i < 6; i++) setTimeout(() => burstIn(top), i * 260); });

