    const a = i / 16 * Math.PI * 2, el = document.createElement("span"); el.className = "spk"; el.style.cssText = "left:50%;top:50%;--s:" + (12 + Math.random() * 14) + "px";
    el.innerHTML = '<svg><use href="#star4"/></svg>'; m.appendChild(el);
    const R = m.offsetWidth * (.42 + Math.random() * .16);
    el.animate([{ transform: "translate(-50%,-50%) translate(" + Math.cos(a) * R * .7 + "px," + Math.sin(a) * R * .7 + "px) scale(.2)", opacity: 0 },
                { transform: "translate(-50%,-50%) translate(" + Math.cos(a) * R + "px," + Math.sin(a) * R + "px) scale(1) rotate(45deg)", opacity: 1, offset: .4 },
                { transform: "translate(-50%,-50%) translate(" + Math.cos(a) * R * 1.12 + "px," + Math.sin(a) * R * 1.12 + "px) scale(.3) rotate(90deg)", opacity: 0 }],
               { duration: 1100 + Math.random() * 400, easing: "ease-out" }).onfinish = () => el.remove();
  }
});

/* the dhol: a bhangra groove made in the browser */
let dholOn = false, dholTimer = 0, nextStep = 0, stepIdx = 0, barCount = 0;
const STEP = 60 / 100 / 4;
const BASS = [0, 6, 8, 14], TREB = [2, 4, 10, 12], SOFT = [3, 7, 11, 15];
function hit(kind, when){
  const c = actx; const d = when - c.currentTime;
  if (kind === "B") { thump(d, 150, 55, .45, .55); noise(d, .04, "lowpass", 1200, .7, .25); }
  else if (kind === "T") { noise(d, .1, "bandpass", 2600, 1.3, .35); thump(d, 520, 380, .08, .08); }
  else noise(d, .06, "bandpass", 3200, 1.5, .12);
}
function schedule(){
  const c = actx; if (!c) return;
  while (nextStep < c.currentTime + .12) {
    const s = stepIdx % 16;
    if (BASS.includes(s)) hit("B", nextStep); if (TREB.includes(s)) hit("T", nextStep); if (SOFT.includes(s)) hit("t", nextStep);
    if (s === 0) { barCount++; if (barCount % 2 === 0) setTimeout(() => burstIn(innerHeight * .45, true), Math.max(0, (nextStep - c.currentTime) * 1000)); }
    nextStep += STEP; stepIdx++;
  }
}
function startDhol(){
  const c = ac(); if (!c) return;
  dholOn = true; stepIdx = 0; barCount = 0; nextStep = c.currentTime + .05; schedule(); dholTimer = setInterval(schedule, 25);
  barS.classList.add("dhol"); $("dhol").setAttribute("aria-pressed", "true"); $("dhol").querySelector("span").textContent = "Stop the dhol";
  if (musicWanted) music.volume = .25;
}
function stopDhol(){
  if (!dholOn) return; dholOn = false; clearInterval(dholTimer);
  barS.classList.remove("dhol"); $("dhol").setAttribute("aria-pressed", "false"); $("dhol").querySelector("span").textContent = "Play the dhol";
  music.volume = .7;
}
$("dhol").addEventListener("click", () => dholOn ? stopDhol() : startDhol());
if ("IntersectionObserver" in window) new IntersectionObserver(([e]) => { if (!e.isIntersecting) stopDhol(); }, { threshold: 0 }).observe(barS);

/* countdown */
const cells = {}; document.querySelectorAll("#count b").forEach(b => cells[b.dataset.u] = b);
function tick(){
  let s = Math.floor((TARGET - Date.now()) / 1000);
  if (s <= 0) { $("count").innerHTML = '<p style="grid-column:1/-1;font-size:1.4rem;font-style:italic">The celebrations have begun. Thank you for being with us!</p>'; return; }
  const d = Math.floor(s / 86400); s -= d * 86400;
  const h = Math.floor(s / 3600); s -= h * 3600;
  const m = Math.floor(s / 60); s -= m * 60;
  cells.d.textContent = d;
  cells.h.textContent = String(h).padStart(2, "0");
  cells.m.textContent = String(m).padStart(2, "0");
  cells.s.textContent = String(s).padStart(2, "0");
  setTimeout(tick, 1000 - Date.now() % 1000);
}
